import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { createLifecycleDiagnostics } from '../../../../scripts/lifecycle-diagnostics.ts';
const results=[];
const fixture=(overrides={})=>{let tick=0n;const output={raw:[],metadata:[],completion:[]};const opts={clock:()=>({utc:'2026-10-15T03:00:00.000Z',monoNs:++tick}),readStat:()=>{throw new Error('unexpected stat read');},listTasks:()=>{throw new Error('unexpected task listing');},appendRaw:s=>{output.raw.push(s);return {bytes:Buffer.byteLength(s)};},appendMetadata:s=>{output.metadata.push(s);return {bytes:Buffer.byteLength(s)};},appendCompletion:s=>{output.completion.push(s);return {bytes:Buffer.byteLength(s)};},...overrides};return {d:createLifecycleDiagnostics(opts),output,opts};};
const check=async(name,fn)=>{await fn();results.push({name,status:'PASS'});};
await check('successful completion remains provisional on disk and requires actual sink acknowledgement',()=>{const f=fixture();const r=f.d.finish({samples:0,failure:null},{sourceExitCode:1,closeFailed:false});const s=JSON.parse(f.output.completion[0]);assert.equal(s.lifecycle.status,'provisional-external-io-verification-required');assert.equal(s.lifecycle.completionWritten,false);assert.equal(s.lifecycle.sourceExitCode,1);assert.equal(r.status,'complete');assert.equal(r.completionWritten,true);assert.equal(r.metadataBytes,Buffer.byteLength(f.output.completion[0]));});
for(const mode of ['full-with-error','partial','throw'])await check('completion '+mode+' never self-attests successful final I/O',()=>{let supplied;const f=fixture({appendCompletion:s=>{supplied=s;if(mode==='throw')throw Object.assign(new Error('/private/path must not persist'),{code:'EIO'});return {bytes:mode==='partial'?7:Buffer.byteLength(s),error:'EIO'};}});const r=f.d.finish({samples:0,failure:null});const s=JSON.parse(supplied);assert.equal(s.lifecycle.status,'provisional-external-io-verification-required');assert.equal(s.lifecycle.completionWritten,false);assert.equal(r.status,'incomplete');assert.equal(r.completionWritten,false);assert.ok(r.issues.includes('METADATA_WRITE_FAILED'));assert.equal(r.bytesUncertain,mode==='throw');assert.ok(!JSON.stringify(r).includes('/private'));assert.ok(r.metadataBytes<=131072);});
await check('known raw failure retains exact cause while oversized completion does not emit',()=>{const a=fixture();const ar=a.d.finish({samples:417,failure:'EIO'});assert.equal(ar.status,'incomplete');assert.equal(JSON.parse(a.output.completion[0]).failure,'EIO');const b=fixture();const br=b.d.finish({samples:417,failure:'x'.repeat(2049)});assert.equal(br.status,'incomplete');assert.equal(br.completionWritten,false);assert.equal(b.output.completion.length,0);assert.ok(br.issues.includes('COMPLETION_CAP'));});
await check('primary close rejection survives independent phase write and context-count failures',async()=>{const primary=Object.freeze({code:'PRIMARY_CLOSE'});const f=fixture({appendMetadata:()=>{throw new Error('/private/diagnostic');}});let caught;try{await f.d.observeClose('product.context.close',()=>Promise.reject(primary),()=>{throw Error('context getter');});}catch(e){caught=e;}assert.equal(caught,primary);const r=f.d.finish({samples:0,failure:null});assert.equal(r.status,'incomplete');assert.ok(r.issues.includes('METADATA_WRITE_FAILED'));assert.ok(r.issues.includes('CONTEXT_COUNT_ERROR'));assert.ok(!JSON.stringify(r).includes('/private/diagnostic'));});
await check('ordinary non-Z list changes retain every bounded process read as exact offsets',()=>{const f=fixture();f.d.beginSweep();f.d.timedRead(1,()=>null);f.d.timedRead(7,()=>null);const list=[{pid:1,state:'S'},{pid:7,state:'R'}];f.d.observeSample(list,JSON.stringify(list),0,'interval');const record=JSON.parse(f.output.metadata[0]);assert.deepEqual(record.processReads,[[1,'1','2'],[7,'3','4']]);assert.equal(record.atomicSnapshot,false);assert.equal(f.d.summary().taskStatReads,0);});
console.log(JSON.stringify({status:'PASS',createdAt:new Date().toISOString(),method:'Offline helper calls with injected I/O only; no browser, Docker, /proc or network.',sourceSha256:createHash('sha256').update(readFileSync('scripts/lifecycle-diagnostics.ts')).digest('hex'),scriptSha256:createHash('sha256').update(readFileSync(new URL(import.meta.url))).digest('hex'),checks:results.length,results},null,2));
